import{_ as a,o as i,c as t,aa as o}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/en/diary/en_stahovani_dat_z_deniku.jpg",g=JSON.parse('{"title":"Downloading Diary Data","description":"","frontmatter":{"title":"Downloading Diary Data","wiki":"en:diary:download"},"headers":[],"relativePath":"en/diary/download.md","filePath":"en/diary/download.md","lastUpdated":1793088561000}'),r={name:"en/diary/download.md"};function d(l,e,s,c,h,f){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="downloading-diary-data" tabindex="-1">Downloading Diary Data <a class="header-anchor" href="#downloading-diary-data" aria-label="Permalink to &quot;Downloading Diary Data&quot;">​</a></h1><p>It is now possible to download data from the diary:</p><img src="'+n+'" alt="" width="600" loading="lazy"><h2 id="official-version-of-the-diary" tabindex="-1">Official Version of the Diary <a class="header-anchor" href="#official-version-of-the-diary" aria-label="Permalink to &quot;Official Version of the Diary&quot;">​</a></h2><p>Downloading the <strong>official version</strong> of the diary generates a ZIP file containing a folder with attachments and individual PDF files: the diary cover sheets and the individual electronically signed days for the selected time period. If no time period is specified, all available data will be downloaded.</p><h2 id="unofficial-version-of-the-diary" tabindex="-1">Unofficial Version of the Diary <a class="header-anchor" href="#unofficial-version-of-the-diary" aria-label="Permalink to &quot;Unofficial Version of the Diary&quot;">​</a></h2><p>Downloading the <strong>unofficial version</strong> of the diary generates a single PDF file containing the diary cover sheets and records for all days within the selected time period, regardless of whether they are signed or unsigned. This output file is referred to as a unofficial version because it <strong>does not contain the digital signatures</strong> of the official source files.</p><p>It can be used for easy full-text searching, viewing, or printing the diary.</p><h2 id="exporting-data-to-excel" tabindex="-1">Exporting Data to Excel <a class="header-anchor" href="#exporting-data-to-excel" aria-label="Permalink to &quot;Exporting Data to Excel&quot;">​</a></h2><p>Exporting data to <strong>Excel</strong> generates an XLS file. The resulting workbook contains individual sections on separate worksheets, with data arranged chronologically.</p><p>The export can also be performed for a selected time period. If no time period is specified, all available data will be downloaded.</p><h2 id="downloading-attachments" tabindex="-1">Downloading Attachments <a class="header-anchor" href="#downloading-attachments" aria-label="Permalink to &quot;Downloading Attachments&quot;">​</a></h2><p>Downloading <strong>attachments</strong> generates a ZIP file containing all diary attachments for the selected time period. If no time period is selected, all attachments will be downloaded.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Depending on the volume of data being downloaded and the quality of the internet connection, it may not be possible to complete the requested export within the export time limit. In such cases, we recommend downloading the data in smaller portions, for example in monthly intervals.</p></div>',14)])])}const m=a(r,[["render",d]]);export{g as __pageData,m as default};
